from hermes_tools import write_file, terminal
code='''from collections import deque
def transform(grid):
    h,w=len(grid),len(grid[0]); a=[row[:] for row in grid]
    outside=set(); q=deque()
    for r in range(h):
        for c in (0,w-1):
            if grid[r][c]==0 and (r,c) not in outside: outside.add((r,c)); q.append((r,c))
    for c in range(w):
        for r in (0,h-1):
            if grid[r][c]==0 and (r,c) not in outside: outside.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and grid[nr][nc]==0 and (nr,nc) not in outside: outside.add((nr,nc)); q.append((nr,nc))
    seen=set(); selected=set()
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=1 or (r,c) in seen: continue
            comp={(r,c)}; seen.add((r,c)); q=deque([(r,c)])
            while q:
                x,y=q.popleft()
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    nx,ny=x+dx,y+dy
                    if 0<=nx<h and 0<=ny<w and grid[nx][ny]==1 and (nx,ny) not in seen: seen.add((nx,ny)); comp.add((nx,ny)); q.append((nx,ny))
            if any((x+dx,y+dy) not in outside and 0<=x+dx<h and 0<=y+dy<w and grid[x+dx][y+dy]==0 for x,y in comp for dx,dy in ((1,0),(-1,0),(0,1),(0,-1))): selected |= comp
    for r,c in selected:
        for dr in (-1,0,1):
            for dc in (-1,0,1):
                nr,nc=r+dr,c+dc
                if 0<=nr<h and 0<=nc<w and grid[nr][nc]==0: a[nr][nc]=3 if (nr,nc) not in outside else 2
    return a
'''
print(write_file('/tmp/candidate_fb.py',code))
